```python
import torch

def rope_frequencies(d, base=10000.0, scaling_factor=1.0):
    if scaling_factor != 1.0:
        base_scaled = base * (scaling_factor ** (d / (d - 2)))
        return 1.0 / (base_scaled ** (torch.arange(0, d, 2).float() / d))
    return 1.0 / (base ** (torch.arange(0, d, 2).float() / d))

def alibi_bias(n_heads, seq_len):
    """ALiBi: no parameters, just a linear bias."""
    slopes = 2 ** (-8 * torch.arange(1, n_heads + 1) / n_heads)
    positions = torch.arange(seq_len)
    return -slopes.unsqueeze(1).unsqueeze(1) * \
           (positions.unsqueeze(0) - positions.unsqueeze(1)).abs()
```

NTK-aware scaling modifies the base frequency rather than linearly interpolating positions, preserving high-frequency local position information while extending global range.
